阅读下面 C++17 代码，判断程序的输出结果。

#include <iostream>
#include <memory>
#include <vector>
#include <stdexcept>
using namespace std;

class Base {
public:
    virtual ~Base() { cout << "B"; }
    virtual int value() const { return 1; }
};

class Derived : public Base {
    vector<int> data;
public:
    Derived() : data{1, 2, 3} {}
    ~Derived() override { cout << "D"; }
    int value() const override { return data.at(1); }
};

int main() {
    try {
        unique_ptr<Base> p = make_unique<Derived>();
        cout << p->value();
        vector<int> v{10, 20};
        cout << v.at(2);
    } catch (const out_of_range&) {
        cout << "E";
    }
    return 0;
}

